// Package canon reads tool arguments exactly as Nia's reference engine, the
// Nia server, does.
//
// An approval, and a release, are bound to the hash of a call's arguments.
// The server computes that hash in JavaScript; nia-edge computes it here.
// The two must agree on every input, byte for byte, or an approved call
// would not be recognised, or the wrong call would be. The cases in
// conformance/canonical.json are the contract: they are generated by the
// server and replayed by this package's tests.
//
// The reference canonical form is what JavaScript produces with
// JSON.parse, object keys sorted, then JSON.stringify:
//
//   - Strings are sequences of UTF-16 code units. Keys sort by code unit,
//     and a \uD800 escape without its pair is kept as it is, so strings are
//     held as []uint16 here, not as Go strings.
//   - A repeated key keeps its last value.
//   - Numbers are IEEE 754 doubles, written the way JavaScript writes them:
//     -0 is "0", a number too large for a double is "null".
//   - Arrays and objects nested deeper than MaxDepth are not canonical: the
//     raw text is hashed instead, as it is for text that is not JSON.
package canon

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"math"
	"slices"
	"strconv"
	"strings"
	"unicode/utf16"
	"unicode/utf8"
)

// MaxDepth is how deep arrays and objects may nest and still be
// canonicalised. It is MAX_CANONICAL_DEPTH in the reference engine.
const MaxDepth = 512

// ErrInvalidUTF8 reports arguments that are not valid UTF-8. The reference
// engine never sees such text (its HTTP layer decodes bytes first), so there
// is no answer to reproduce: the caller must refuse the call.
var ErrInvalidUTF8 = errors.New("canon: text is not valid UTF-8")

// errNotJSON and errTooDeep are internal: both mean "hash the raw text".
var (
	errNotJSON = errors.New("canon: not JSON")
	errTooDeep = errors.New("canon: nested too deep")
)

type kind uint8

const (
	kindNull kind = iota
	kindFalse
	kindTrue
	kindNumber
	kindString
	kindArray
	kindObject
)

type member struct {
	key   []uint16
	value *node
}

type node struct {
	kind    kind
	number  float64
	text    []uint16
	items   []*node
	members []member
}

// Canonical returns the canonical JSON of tool arguments. Empty text reads as
// null, as in the reference engine. ok is false when the text is not JSON or
// nests deeper than MaxDepth; the raw text is then what gets hashed.
func Canonical(text string) (canonical string, ok bool, err error) {
	if !utf8.ValidString(text) {
		return "", false, ErrInvalidUTF8
	}
	if text == "" {
		text = "null"
	}
	p := parser{data: text}
	root, parseErr := p.document()
	if parseErr != nil {
		return "", false, nil
	}
	out := make([]byte, 0, len(text))
	return string(appendNode(out, root)), true, nil
}

// ArgumentsHash is the hash an approval or a release is bound to:
// SHA-256, in hexadecimal, of the tool name, a NUL byte, and the canonical
// arguments (or the raw text when they are not canonical JSON).
func ArgumentsHash(tool, text string) (string, error) {
	if !utf8.ValidString(tool) {
		return "", ErrInvalidUTF8
	}
	canonical, ok, err := Canonical(text)
	if err != nil {
		return "", err
	}
	if !ok {
		canonical = text
	}
	sum := sha256.Sum256([]byte(tool + "\x00" + canonical))
	return hex.EncodeToString(sum[:]), nil
}

// ---------------------------------------------------------------- parsing

// parser accepts the JSON grammar of ECMA-404, which is what JSON.parse
// accepts: nothing more (no comments, no trailing commas, no NaN), and the
// four whitespace characters only.
type parser struct {
	data string
	pos  int
}

func (p *parser) document() (*node, error) {
	p.space()
	root, err := p.value(0)
	if err != nil {
		return nil, err
	}
	p.space()
	if p.pos != len(p.data) {
		return nil, errNotJSON
	}
	return root, nil
}

func (p *parser) space() {
	for p.pos < len(p.data) {
		switch p.data[p.pos] {
		case ' ', '\t', '\n', '\r':
			p.pos++
		default:
			return
		}
	}
}

// value parses one value. depth is the number of arrays and objects around it.
func (p *parser) value(depth int) (*node, error) {
	if p.pos >= len(p.data) {
		return nil, errNotJSON
	}
	switch c := p.data[p.pos]; {
	case c == '{':
		if depth >= MaxDepth {
			return nil, errTooDeep
		}
		return p.object(depth + 1)
	case c == '[':
		if depth >= MaxDepth {
			return nil, errTooDeep
		}
		return p.array(depth + 1)
	case c == '"':
		text, err := p.str()
		if err != nil {
			return nil, err
		}
		return &node{kind: kindString, text: text}, nil
	case c == '-' || (c >= '0' && c <= '9'):
		return p.number()
	case p.literal("null"):
		return &node{kind: kindNull}, nil
	case p.literal("true"):
		return &node{kind: kindTrue}, nil
	case p.literal("false"):
		return &node{kind: kindFalse}, nil
	}
	return nil, errNotJSON
}

func (p *parser) literal(word string) bool {
	if strings.HasPrefix(p.data[p.pos:], word) {
		p.pos += len(word)
		return true
	}
	return false
}

func (p *parser) array(depth int) (*node, error) {
	p.pos++ // [
	result := &node{kind: kindArray}
	p.space()
	if p.pos < len(p.data) && p.data[p.pos] == ']' {
		p.pos++
		return result, nil
	}
	for {
		p.space()
		item, err := p.value(depth)
		if err != nil {
			return nil, err
		}
		result.items = append(result.items, item)
		p.space()
		if p.pos >= len(p.data) {
			return nil, errNotJSON
		}
		switch p.data[p.pos] {
		case ',':
			p.pos++
		case ']':
			p.pos++
			return result, nil
		default:
			return nil, errNotJSON
		}
	}
}

func (p *parser) object(depth int) (*node, error) {
	p.pos++ // {
	result := &node{kind: kindObject}
	// Position of each key in members: a repeated key replaces its value.
	seen := map[string]int{}
	p.space()
	if p.pos < len(p.data) && p.data[p.pos] == '}' {
		p.pos++
		return result, nil
	}
	for {
		p.space()
		if p.pos >= len(p.data) || p.data[p.pos] != '"' {
			return nil, errNotJSON
		}
		key, err := p.str()
		if err != nil {
			return nil, err
		}
		p.space()
		if p.pos >= len(p.data) || p.data[p.pos] != ':' {
			return nil, errNotJSON
		}
		p.pos++
		p.space()
		value, err := p.value(depth)
		if err != nil {
			return nil, err
		}
		id := unitsKey(key)
		if at, repeated := seen[id]; repeated {
			result.members[at].value = value
		} else {
			seen[id] = len(result.members)
			result.members = append(result.members, member{key: key, value: value})
		}
		p.space()
		if p.pos >= len(p.data) {
			return nil, errNotJSON
		}
		switch p.data[p.pos] {
		case ',':
			p.pos++
		case '}':
			p.pos++
			return result, nil
		default:
			return nil, errNotJSON
		}
	}
}

// unitsKey is a map key that is equal exactly when two code unit sequences are.
func unitsKey(units []uint16) string {
	raw := make([]byte, 0, 2*len(units))
	for _, unit := range units {
		raw = append(raw, byte(unit>>8), byte(unit))
	}
	return string(raw)
}

// str parses a string starting at its opening quote into UTF-16 code units.
func (p *parser) str() ([]uint16, error) {
	p.pos++ // "
	units, next, ok := unquote(p.data, p.pos)
	if !ok {
		return nil, errNotJSON
	}
	p.pos = next
	return units, nil
}

// unquote decodes the body of a JSON string that starts at data[from], up to
// its closing quote, and returns the position after that quote.
func unquote(data string, from int) (units []uint16, next int, ok bool) {
	units = []uint16{}
	for pos := from; pos < len(data); {
		c := data[pos]
		switch {
		case c == '"':
			return units, pos + 1, true
		case c < 0x20:
			// Control characters must be escaped.
			return nil, 0, false
		case c == '\\':
			pos++
			if pos >= len(data) {
				return nil, 0, false
			}
			switch data[pos] {
			case '"':
				units = append(units, '"')
			case '\\':
				units = append(units, '\\')
			case '/':
				units = append(units, '/')
			case 'b':
				units = append(units, '\b')
			case 'f':
				units = append(units, '\f')
			case 'n':
				units = append(units, '\n')
			case 'r':
				units = append(units, '\r')
			case 't':
				units = append(units, '\t')
			case 'u':
				if pos+4 >= len(data) {
					return nil, 0, false
				}
				var unit uint16
				for _, digit := range []byte(data[pos+1 : pos+5]) {
					value, isHex := hexValue(digit)
					if !isHex {
						return nil, 0, false
					}
					unit = unit<<4 | uint16(value)
				}
				// Any code unit, a surrogate without its pair included.
				units = append(units, unit)
				pos += 4
			default:
				return nil, 0, false
			}
			pos++
		default:
			// The text is valid UTF-8, so this is a whole character and it is
			// not a surrogate: AppendRune encodes it as it is.
			r, size := utf8.DecodeRuneInString(data[pos:])
			units = utf16.AppendRune(units, r)
			pos += size
		}
	}
	return nil, 0, false
}

func hexValue(c byte) (byte, bool) {
	switch {
	case c >= '0' && c <= '9':
		return c - '0', true
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10, true
	case c >= 'A' && c <= 'F':
		return c - 'A' + 10, true
	}
	return 0, false
}

// number parses -?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)? and nothing
// else. The grammar is checked here because strconv.ParseFloat also accepts
// spellings JSON does not have (hexadecimal, "Inf", "NaN").
func (p *parser) number() (*node, error) {
	start := p.pos
	if p.data[p.pos] == '-' {
		p.pos++
	}
	if p.pos >= len(p.data) {
		return nil, errNotJSON
	}
	switch c := p.data[p.pos]; {
	case c == '0':
		p.pos++
	case c >= '1' && c <= '9':
		p.digits()
	default:
		return nil, errNotJSON
	}
	if p.pos < len(p.data) && p.data[p.pos] == '.' {
		p.pos++
		if p.digits() == 0 {
			return nil, errNotJSON
		}
	}
	if p.pos < len(p.data) && (p.data[p.pos] == 'e' || p.data[p.pos] == 'E') {
		p.pos++
		if p.pos < len(p.data) && (p.data[p.pos] == '+' || p.data[p.pos] == '-') {
			p.pos++
		}
		if p.digits() == 0 {
			return nil, errNotJSON
		}
	}
	// The nearest double. Out of range, ParseFloat returns ±Inf with
	// ErrRange, which is the value JavaScript reads too.
	value, err := strconv.ParseFloat(p.data[start:p.pos], 64)
	if err != nil && !errors.Is(err, strconv.ErrRange) {
		return nil, errNotJSON
	}
	return &node{kind: kindNumber, number: value}, nil
}

func (p *parser) digits() int {
	start := p.pos
	for p.pos < len(p.data) && p.data[p.pos] >= '0' && p.data[p.pos] <= '9' {
		p.pos++
	}
	return p.pos - start
}

// ------------------------------------------------------------- serialising

func appendNode(out []byte, n *node) []byte {
	switch n.kind {
	case kindNull:
		return append(out, "null"...)
	case kindFalse:
		return append(out, "false"...)
	case kindTrue:
		return append(out, "true"...)
	case kindNumber:
		return appendNumber(out, n.number)
	case kindString:
		return appendQuoted(out, n.text)
	case kindArray:
		out = append(out, '[')
		for index, item := range n.items {
			if index > 0 {
				out = append(out, ',')
			}
			out = appendNode(out, item)
		}
		return append(out, ']')
	default:
		members := slices.Clone(n.members)
		// Keys are distinct, so the order is total and an unstable sort is exact.
		slices.SortFunc(members, func(a, b member) int { return slices.Compare(a.key, b.key) })
		out = append(out, '{')
		for index, m := range members {
			if index > 0 {
				out = append(out, ',')
			}
			out = appendQuoted(out, m.key)
			out = append(out, ':')
			out = appendNode(out, m.value)
		}
		return append(out, '}')
	}
}

const lowerHex = "0123456789abcdef"

// appendQuoted writes a string as JSON.stringify does: only the quote, the
// backslash and the control characters are escaped, a surrogate pair is
// written as its character, and a surrogate without its pair as \udXXX.
func appendQuoted(out []byte, units []uint16) []byte {
	out = append(out, '"')
	for index := 0; index < len(units); index++ {
		unit := units[index]
		switch {
		case unit == '"':
			out = append(out, '\\', '"')
		case unit == '\\':
			out = append(out, '\\', '\\')
		case unit == '\b':
			out = append(out, '\\', 'b')
		case unit == '\f':
			out = append(out, '\\', 'f')
		case unit == '\n':
			out = append(out, '\\', 'n')
		case unit == '\r':
			out = append(out, '\\', 'r')
		case unit == '\t':
			out = append(out, '\\', 't')
		case unit < 0x20:
			out = appendEscape(out, unit)
		case unit >= 0xd800 && unit <= 0xdbff && index+1 < len(units) && units[index+1] >= 0xdc00 && units[index+1] <= 0xdfff:
			out = utf8.AppendRune(out, utf16.DecodeRune(rune(unit), rune(units[index+1])))
			index++
		case unit >= 0xd800 && unit <= 0xdfff:
			out = appendEscape(out, unit)
		default:
			out = utf8.AppendRune(out, rune(unit))
		}
	}
	return append(out, '"')
}

func appendEscape(out []byte, unit uint16) []byte {
	return append(out, '\\', 'u', lowerHex[unit>>12], lowerHex[unit>>8&0xf], lowerHex[unit>>4&0xf], lowerHex[unit&0xf])
}

// appendNumber writes a double as JavaScript's Number::toString does, which
// is what JSON.stringify uses: the shortest digits that read back as the
// same double, positional between 1e-6 and 1e21, with an exponent outside.
func appendNumber(out []byte, value float64) []byte {
	if math.IsInf(value, 0) || math.IsNaN(value) {
		return append(out, "null"...)
	}
	if value == 0 {
		// Negative zero too.
		return append(out, '0')
	}
	if value < 0 {
		out = append(out, '-')
		value = -value
	}
	// 'e' with precision -1: d.ddde±dd, the fewest digits that ParseFloat
	// reads back as the same value.
	scientific := strconv.FormatFloat(value, 'e', -1, 64)
	mantissa, exponentText, _ := strings.Cut(scientific, "e")
	exponent, err := strconv.Atoi(exponentText)
	if err != nil {
		panic("canon: unexpected float format " + scientific)
	}
	digits := strings.Replace(mantissa, ".", "", 1)
	count := len(digits)
	// The value is 0.digits × 10^point.
	point := exponent + 1
	switch {
	case count <= point && point <= 21:
		out = append(out, digits...)
		for range point - count {
			out = append(out, '0')
		}
	case 0 < point && point <= 21:
		out = append(out, digits[:point]...)
		out = append(out, '.')
		out = append(out, digits[point:]...)
	case -6 < point && point <= 0:
		out = append(out, '0', '.')
		for range -point {
			out = append(out, '0')
		}
		out = append(out, digits...)
	default:
		out = append(out, digits[0])
		if count > 1 {
			out = append(out, '.')
			out = append(out, digits[1:]...)
		}
		out = append(out, 'e')
		if exponent < 0 {
			out = append(out, '-')
			exponent = -exponent
		} else {
			out = append(out, '+')
		}
		out = strconv.AppendInt(out, int64(exponent), 10)
	}
	return out
}

// ------------------------------------------------------------ repeated keys

// HasDuplicateKeys reports whether a JSON text has an object with the same
// key twice. One parser keeps the last value, another the first, so a call
// whose arguments repeat a key could run with arguments Nia did not evaluate.
//
// It is a scan of the raw text, not a parse, and it reproduces the reference
// engine's hasDuplicateKeys step for step, on text that is not JSON as well:
// the two engines must refuse the same calls.
func HasDuplicateKeys(text string) (bool, error) {
	if !utf8.ValidString(text) {
		return false, ErrInvalidUTF8
	}
	// One entry per open array or object; nil for an array.
	var stack []map[string]struct{}
	expectKey := false
	for i := 0; i < len(text); {
		switch c := text[i]; c {
		case '"':
			// Up to the next quote that no backslash precedes. A backslash
			// takes the character after it, whatever it is.
			j := i + 1
			for j < len(text) && text[j] != '"' {
				if text[j] == '\\' {
					j++
					if j < len(text) {
						_, size := utf8.DecodeRuneInString(text[j:])
						j += size
					}
				} else {
					j++
				}
			}
			if expectKey && len(stack) > 0 {
				body := text[i+1 : min(j, len(text))]
				units, next, ok := unquote(body+`"`, 0)
				if !ok || next != len(body)+1 {
					// Not a JSON string: the text is unreadable, and it is
					// refused elsewhere as such.
					return false, nil
				}
				keys := stack[len(stack)-1]
				id := unitsKey(units)
				if _, repeated := keys[id]; repeated {
					return true, nil
				}
				keys[id] = struct{}{}
				expectKey = false
			}
			i = j + 1
			continue
		case '{':
			stack = append(stack, map[string]struct{}{})
			expectKey = true
		case '[':
			stack = append(stack, nil)
			expectKey = false
		case '}', ']':
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
			expectKey = false
		case ',':
			expectKey = len(stack) > 0 && stack[len(stack)-1] != nil
		}
		i++
	}
	return false, nil
}
